import{_ as u,a0 as o,w as r,s as a,ao as s,I as n,a1 as e,A as l,x as i}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const w=JSON.parse('{"title":"可以快速保存、訪問和粘貼文本片段的Unity漂亮工具 | LCTT x X-CMD","titleTemplate":false,"description":"可以快速保存、訪問和粘貼文本片段的Unity漂亮工具 | LCTT (201311) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"可以快速保存、訪問和粘貼文本片段的Unity漂亮工具 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"可以快速保存、訪問和粘貼文本片段的Unity漂亮工具 | LCTT (201311) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201311/Save, Access And Quickly Paste Text Snippets With This Nifty Unity Launcher Tool","title":"可以快速保存、訪問和粘貼文本片段的Unity漂亮工具","tag":"201311","desc":""},"relativePath":"201311/Save, Access And Quickly Paste Text Snippets With This Nifty Unity Launcher Tool.md","filePath":"[post].md"}'),d={name:"201311/Save, Access And Quickly Paste Text Snippets With This Nifty Unity Launcher Tool.md"};function T(m,t,y,f,S,x){const p=o("Link");return r(),a("div",null,[t[16]||(t[16]=s('<h1 id="可以快速保存、訪問和粘貼文本片段的unity漂亮工具" tabindex="-1">可以快速保存、訪問和粘貼文本片段的Unity漂亮工具 <a class="header-anchor" href="#可以快速保存、訪問和粘貼文本片段的unity漂亮工具" aria-label="Permalink to “可以快速保存、訪問和粘貼文本片段的Unity漂亮工具”">​</a></h1><p><strong>反覆鍵入特定的信息 - 如電子郵件地址或家庭地址，詳細的終端命令，及時發送用户喜愛的電視節目的資訊 - 可是件苦差事。</strong></p><p><img src="http://www.omgubuntu.co.uk/wp-content/uploads/2013/10/Screen-Shot-2013-10-31-at-13.04.jpg" alt=""><em>Snippets – 方便的訪問存儲的文本的方法</em></p><p>謝天謝地，這個世界上有一些工具可以幫助我們（做這些事兒）。</p><p><em>‘Snippets’</em> 就是Unity中這種組件之一。 這是一個簡單的啓動程序小工具，它讓你在一個文件中保存和存儲摘下來的內容，然後當你需要的時候從Unity的一個快速列表裏複製到剪貼板。</p><p>在某些人把他的內褲扔到我的臉上之前，我得説Snippets不是唯一的這種工具，它甚至不是第一個提供這一系列功能的。但是它獨特的是通過Unity啓動器來提供這一系列功能。</p><p>這個軟件具功能不錯又足夠簡單，提供以下功能:</p><ul><li>添加、訪問存儲在txt文件中的文本段</li><li>在快速列表裏查看保存的文本段</li><li>點擊文本段就可以複製到剪貼板</li><li>提供了把剪貼板中的內容保存到txt文件的選項</li></ul><p>儘管它不是一個“智能”的剪貼板管理工具 – 它只是列出了你特別添加的項目；它不會列出你最近的剪貼板項目歷史，但仍然是一個非常方便的小工具。</p><p>###怎樣為Unity安裝Snippets###</p><p>想要使用這個漂亮的啓動器項目，你需要先安裝一個命令列剪貼板工具XClip。點擊下面的按鈕（鏈接）從軟件中心安裝。</p>',11)),n("ul",null,[n("li",null,[e(p,{href:"apt://xclip"},{default:l(()=>[...t[0]||(t[0]=[i("點擊以在Ubuntu裏安裝XClip",-1)])]),_:1})])]),t[17]||(t[17]=n("p",null,"下一步，下載下面的‘Snippets’壓縮文件。這包含了剩餘所有的使用這個應用所需要的東西。",-1)),n("ul",null,[n("li",null,[e(p,{href:"https://www.dropbox.com/s/ha6lngizmz78srv/snippets%20by%20stinkeye.tar.gz"},{default:l(()=>[...t[1]||(t[1]=[i("下載‘Snippets’Unity啓動器",-1)])]),_:1})])]),t[18]||(t[18]=s(`<p>當這個壓縮文件下完之後你就可以解壓了。進入生成的文件夾，然後按Ctrl+H顯示隱藏的文件。移動文件夾‘.snippets-launcher‘到你的主文件夾中。<strong>如果不這麼做，這個組件將無法正常工作。</strong></p><p>下一步是安裝啓動器項目。這是被一個你剛搬到文件夾裏面的腳本關照的，但它不具有可執行的權限（需要安裝），因此，我們首先需要關照它一下。</p><p>打開一個新的終端窗口在裏面小心的鍵入下面的命令：</p><pre><code>cd .snippets-launcher/ &amp;&amp; chmod +x snippets.sh
./snippets.sh
</code></pre><p>就是這樣；Snippets應該已經整裝待發了。打開Unity Dash搜索Snippets然後把它拖到啓動器上去：</p><ul><li>左鍵點擊啓動器打開可以添加你的文本段的文本文件</li><li>右鍵點擊啓動器上的項目打開快速列表</li></ul><p>快速列表裏的選項:</p><ul><li>左鍵點擊文本段以添加到剪貼板</li><li>左鍵點擊“日期”可以複製當前日期</li><li>點擊“添加剪貼板內容”可以把當前剪貼板中的內容加入到.txt文件中（譯註：實際上保存的文本是存儲在一個文本文件中）</li><li>在添加一個項目到.txt文件後點擊“更新啓動器”</li></ul>`,8)),n("p",null,[t[3]||(t[3]=i("更多關於這個懶人的工具信息盡在",-1)),e(p,{href:"http://ubuntuforums.org/showthread.php?t=2184916"},{default:l(()=>[...t[2]||(t[2]=[i("Ubuntu論壇",-1)])]),_:1}),t[4]||(t[4]=i("，在那裏它的開發者，“Stinkeye”,會很高興地提供幫助。",-1))]),t[19]||(t[19]=n("hr",null,null,-1)),n("p",null,[t[6]||(t[6]=i("via: ",-1)),e(p,{href:"http://www.omgubuntu.co.uk/2013/10/unity-launcher-clipboard-snippets-item"},{default:l(()=>[...t[5]||(t[5]=[i("http://www.omgubuntu.co.uk/2013/10/unity-launcher-clipboard-snippets-item",-1)])]),_:1})]),n("p",null,[t[9]||(t[9]=i("譯者：",-1)),e(p,{href:"https://github.com/%E8%AD%AF%E8%80%85ID"},{default:l(()=>[...t[7]||(t[7]=[i("crowner",-1)])]),_:1}),t[10]||(t[10]=i(" 校對：",-1)),e(p,{href:"https://github.com/wxy"},{default:l(()=>[...t[8]||(t[8]=[i("wxy",-1)])]),_:1})]),n("p",null,[t[13]||(t[13]=i("本文由 ",-1)),e(p,{href:"https://github.com/LCTT/TranslateProject"},{default:l(()=>[...t[11]||(t[11]=[i("LCTT",-1)])]),_:1}),t[14]||(t[14]=i(" 原創翻譯，",-1)),e(p,{href:"http://linux.cn/"},{default:l(()=>[...t[12]||(t[12]=[i("Linux中國",-1)])]),_:1}),t[15]||(t[15]=i(" 榮譽推出",-1))])])}const U=u(d,[["render",T]]);export{w as __pageData,U as default};
